    <script>

  // ---- tuning dials ---------------------------------------------------------
  const focalLength = 6;
  const upstagenessAddedPerRemainingDay = 1;


  // ---- scene measurements (refreshed on load + resize) ----------------------
  const sceneContainerElement = document.getElementById("Viewport");
  let sceneWidth, sceneHeight, vanishingPointX, horizonY;
  let prosceniumY, prosceniumLength, upstageY, cornerLeft, cornerRight;

  function refreshSceneGeometry() {
    sceneWidth  = sceneContainerElement.clientWidth;
    sceneHeight = sceneContainerElement.clientHeight;
    vanishingPointX = sceneWidth / 2;
    horizonY        = sceneHeight / 2;
    prosceniumY      = sceneHeight * 0.9;
    prosceniumLength = sceneWidth * 0.8;
    upstageY         = sceneHeight * 0.35;
    cornerLeft  = (sceneWidth - prosceniumLength) / 2;
    cornerRight = sceneWidth - (sceneWidth - prosceniumLength) / 2;
  }

      // ---- pyramid rows: fewest rows that hold every assignment ------------------
      function getTriangularNumber(n) {
        if (n < 0) return 0;
        return (n * (n + 1)) / 2;
      }

  let rows, slots;
  for (let i = 1; i <= ArrayOfAllAssignmentObjects.length; i++) {
    if (getTriangularNumber(i) >= ArrayOfAllAssignmentObjects.length) {
      rows = i;
      slots = getTriangularNumber(i);
      break;
    }
  }

  // ---- maths helpers --------------------------------------------------------
  function ConvertDaysLeftIntoDepth(daysLeft) {
    return daysLeft * upstagenessAddedPerRemainingDay;
  }
  function ConvertUpstagenessIntoScaleRatio(upstagenessTotal) {
    return focalLength / (focalLength + upstagenessTotal);
  }
  function scaleRatioFor(oneAssignment) {              // one source of truth
    const daysLeft = CalculateDaysUntilTheDeadline(oneAssignment);
    return ConvertUpstagenessIntoScaleRatio(ConvertDaysLeftIntoDepth(daysLeft));
  }

  // ---- position helpers -----------------------------------------------------
  function getRowAndSlot(i) {
    let row = 0;
    let slotsInThisRow = rows;                 // row 0 = widest (front)
    while (i >= slotsInThisRow) {
      i = i - slotsInThisRow;
      row = row + 1;
      slotsInThisRow = slotsInThisRow - 1;     // each row back has one fewer
    }
    return { row, slotInRow: i, slotsInThisRow };
  }

  function verticalFloorPosition(oneAssignment) {
    return upstageY + (prosceniumY - upstageY) * scaleRatioFor(oneAssignment);
  }

  function horizontalFloorPosition(oneAssignment, idx) {
    const place = getRowAndSlot(idx);
    const thisRowWidth = prosceniumLength * (place.slotsInThisRow / rows);
    const thisRowLeft  = (sceneWidth - thisRowWidth) / 2;

    let slotFraction = (place.slotInRow + 0.5) / place.slotsInThisRow;
    if (place.row % 2 === 1) slotFraction = 1 - slotFraction;   // snake: odd rows reverse

    return thisRowLeft + slotFraction * thisRowWidth;
  }

  // ---- per-runner attribute functions ---------------------------------------
  function runnerRadius(oneAssignment) {
    return 100 * scaleRatioFor(oneAssignment);
  }

  function runnerFloorTransform(oneAssignment, idx) {
    return `translate(${horizontalFloorPosition(oneAssignment, idx)}, ${verticalFloorPosition(oneAssignment)})`;
  }

  // ---- per-runner skews -----------------
      function runnerSkewTransform(oneAssignment, idx) {
        const thisX = horizontalFloorPosition(oneAssignment, idx);
        const edgeFactor = (thisX - vanishingPointX) / (sceneWidth / 2);
        const skinniness = 1 - Math.abs(edgeFactor) * 0.5;
        const turn       = edgeFactor * 25;
        return `rotate(${turn}) scale(${skinniness}, 1)`;   // ← was scale(0.3, 2)
      }

  // ---- drawing the stage ------
  function DrawTheStage() {
    svgSelection.append("line")
      .attr("x1", 0).attr("y1", horizonY)
      .attr("x2", sceneWidth).attr("y2", horizonY)
      .attr("stroke", "#ffffff").attr("stroke-width", 3);

    svgSelection.append("line")
      .attr("x1", 0).attr("y1", sceneHeight)
      .attr("x2", vanishingPointX).attr("y2", horizonY)
      .attr("stroke", "#ffffff").attr("stroke-width", 3);

    svgSelection.append("line")
      .attr("x1", sceneWidth).attr("y1", sceneHeight)
      .attr("x2", vanishingPointX).attr("y2", horizonY)
      .attr("stroke", "#ffffff").attr("stroke-width", 3);
  }


  // ---- drawing the RECTANGLES ------
    const everyRunnerGroup = svgSelection.append("g")
      .selectAll("g.OneRunnerGroup")
      .data(ArrayOfAllAssignmentObjects)
      .join("g")
        .attr("class", "OneRunnerGroup")
        .attr("transform", runnerFloorTransform);

    everyRunnerGroup.append("rect")
      .attr("width",  oneAssignment => 40 * scaleRatioFor(oneAssignment))    // near = wide
      .attr("height", oneAssignment => 120 * scaleRatioFor(oneAssignment))   // near = tall
      .attr("x", oneAssignment => -(40 * scaleRatioFor(oneAssignment)) / 2)  // centre horizontally
      .attr("y", oneAssignment => -(120 * scaleRatioFor(oneAssignment)))     // feet on the floor point
      .attr("fill", "none")
      .attr("pointer-events", "all")
      .attr("stroke", "#ff6ec7")
      .attr("stroke-width", 3)
      .attr("transform", runnerSkewTransform);

    everyRunnerGroup.append("title")
      .text(oneAssignment => JSON.stringify(oneAssignment.dueDate - new Date(), null, 2));
  }

  //---- callback to draw everything ---------------
                    function DrawEverything() {
                      svgSelection.selectAll("*").remove();
                      svgSelection.attr("viewBox", `0 0 ${sceneWidth} ${sceneHeight}`);
                      DrawTheStage();
                      DrawAllCircles();
  // ---- go -------------------------------------------------------------------
  document.addEventListener("DOMContentLoaded", () => {
    refreshSceneGeometry();
    DrawEverything();
  window.addEventListener("resize", () => {
    refreshSceneGeometry();
    DrawEverything();
  });

