function FindRunnerNearestTo(pointerX, pointerY) {
  const stillActive = ArrayOfAllAssignmentObjects.filter(oneAssignment =>
    !SetOfCompletedAssignmentNames.has(oneAssignment.assignmentName)
  );

  let nearestRunner = null;
  let smallestDistance = Infinity;

    stillActive.forEach(oneAssignment => {
